def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {k: v for k, v in opponents_status.items() if v.get('alive')}
    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    cindy_bid = None
    active_non_cindy = 0
    for name, opp in alive.items():
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if name == 'Cindy':
                cindy_bid = float(bid)
            else:
                if float(bid) > 0:
                    active_non_cindy += 1

    tight_supply = supply <= 17
    very_tight = supply <= 15

    if hp <= 2 or no_water_days >= 2:
        bid = 66.0 if not very_tight else 69.0
    elif hp <= 4 or no_water_days >= 1:
        bid = 44.0 if not tight_supply else 54.0
    else:
        bid = 16.0 if not tight_supply else 24.0

    if active_non_cindy > 0:
        non_cindy_max = 0.0
        for name, opp in alive.items():
            if name == 'Cindy':
                continue
            prev = opp.get('previous_trace', {})
            pbid = prev.get('bid') if prev else None
            if pbid is not None:
                non_cindy_max = max(non_cindy_max, float(pbid))
        if non_cindy_max > 0:
            bid = max(bid, min(58.0, non_cindy_max + 2.0))

    if cindy_bid is not None and cindy_bid >= 90.0 and hp > 4 and no_water_days == 0:
        bid = min(bid, 18.0 if not tight_supply else 26.0)

    if budget < bid:
        bid = budget

    if budget <= 25:
        bid = min(bid, budget)
    elif budget <= 60 and hp > 2 and no_water_days == 0:
        bid = min(bid, 28.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Use only yesterday's immediate trace.
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how competitive the market was.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Convert supply to a rough expected number of allocations we can cover.
    # (Only used to choose aggressiveness.)
    supply_units = int(supply / WATER_REQ) if WATER_REQ > 0 else 0

    # Base bid: target around the observed aggressive range but not always the max.
    # If my HP is healthy, try to outbid the second-highest slightly.
    # If my HP is low, bid closer to a safer threshold to preserve budget.
    if hp >= 6:
        target = max(DAILY_SALARY * 0.55, second_prev_bid + 3.0)
        if highest_prev_bid > DAILY_SALARY * 0.85:
            target = max(target, DAILY_SALARY * 0.75)
    elif hp >= 3:
        target = max(DAILY_SALARY * 0.65, second_prev_bid + 1.5)
        if highest_prev_bid > DAILY_SALARY * 0.85:
            target = max(target, DAILY_SALARY * 0.85)
    else:
        # Critical HP: bid high enough to secure water but cap by budget.
        target = max(DAILY_SALARY * 0.9, highest_prev_bid * 0.95)

    # Adjust for supply: if supply is higher, competition may be less intense.
    if supply >= 20.0:
        target *= 0.95
    elif supply <= 16.0:
        target *= 1.05

    # Ensure we don't bid more than budget.
    target = float(target)
    bid = min(budget, target)

    # If budget is too low, still bid something positive if needed.
    if bid <= 0.0:
        return 0.0

    # Small strategy: if I've already gone without water, increase urgency.
    if no_water_days >= 1:
        bid = min(budget, bid + 5.0)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.7)

    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max_prev * 1.1)
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.9, DAILY_SALARY * 0.6))

    return float(max(0, bid))
